  max-height: 88vh;
  overflow: auto;
  background: #fff;
  border-radius: 22px;
  border: 1px solid rgba(8, 38, 58, 0.12);
  box-shadow: 0 28px 80px rgba(8, 38, 58, 0.28);
  padding: 1.25rem;
}

